import flowio, numpy as np, os
FCS='/task/input/fcs/'
DET=['V450-A','V525-A','B530-A','B710-A','YG586-A','YG780-A','R670-A','R780-A']
_cache={}
def _g(t,key,default=None):
    k=key.upper()
    for cand in (key, key.lower(), key.lstrip('$'), key.lstrip('$').lower()):
        if cand in t: return t[cand]
    # synonyms
    syn={'$PNS':['PAR','$PNS','par','PAR'],'$TOT':['TOT','$TOT','tot']} 
    if key in syn:
        for c in syn[key]:
            for cand in (c, c.lower()):
                if cand in t: return t[cand]
    return default
def load(name):
    name=os.path.basename(name)
    if name in _cache: return _cache[name]
    ff=flowio.FlowData(FCS+name)
    t=ff.text
    pns=int(_g(t,'$PNS'))
    names=[_g(t,'$P%dN'%i) for i in range(1,pns+1)]
    volts={_g(t,'$P%dN'%i): float(_g(t,'$P%dV'%i,'nan')) for i in range(1,pns+1)}
    arr=ff.events.astype(np.float64)
    idx={n:i for i,n in enumerate(names)}
    spill=_g(t,'$SPILL')
    _cache[name]=(arr,names,idx,volts,int(_g(t,'$TOT')),spill)
    return _cache[name]
def col(name,ch):
    d=load(name); return d[0][:,d[2][ch]]
